window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2df02b29ca908172"]={"versions": [{"id": "FIG-2df02b29ca908172", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Teilschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 4m). Das Diagramm beschreibt die Funktion <code>E2E_P04mCheck()</code> auf der Prüfseite (Client- und Serverseite) zur Extraktion des Sequenzzählers aus dem empfangenen Datenstrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsbereich / Kontext:</strong> Funktion <code>E2E_P04mCheck()</code>\n</li><li><strong>Eingangsdaten / Datenstruktur:</strong> Byte-Array <code>Data[]</code> mit Adressierung über einen konfigurierten Offset <code>Offset</code>\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>\n</li><li><strong>Knotenelemente:</strong> Startknoten (Initial Node), eine Aktionsstufe (Action) sowie ein Endknoten (Activity Final Node)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und geht direkt in die Verarbeitungsaktion über.\n</li><li>In der Aktion werden zwei Bytes aus dem Array <code>Data</code> an den Positionen <code>Offset+2</code> und <code>Offset+3</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) ausgelesen und in die lokale Variable <code>ReceivedCounter</code> (<code>uint16</code>) geschrieben.\n</li><li>Nach Ausführung der Zuweisung wird der Kontrollfluss zum Aktivitätsendknoten weitergeleitet, womit dieser Teilschritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[PRS_E2E_00776]</code> / <code>RS_E2E_08539</code>. Entwickler müssen sicherstellen, dass das übergebene PDU-Datenarray mindestens die Länge <code>Offset + 4</code> aufweist (bzw. zuvor über den Längen-Check validiert wurde), um Pufferüberläufe beim Zugriff auf <code>Offset+2</code> und <code>Offset+3</code> zu verhindern. Die Auswertung der Byte-Reihenfolge muss strikt in Big-Endian-Konvention erfolgen, unabhängig von der nativen Endianness der Host-CPU.</p>"}, {"id": "FIG-befc310f0bc857c1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Teilschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 4m). Das Diagramm beschreibt die Funktion <code>E2E_P04mCheck()</code> auf der Prüfseite (Client- und Serverseite) zur Extraktion des Sequenzzählers aus dem empfangenen Datenstrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätsbereich / Kontext:</strong> Funktion <code>E2E_P04mCheck()</code>\n</li><li><strong>Eingangsdaten / Datenstruktur:</strong> Byte-Array <code>Data[]</code> mit Adressierung über einen konfigurierten Offset <code>Offset</code>\n</li><li><strong>Lokale Variable:</strong> <code>ReceivedCounter</code> vom Datentyp <code>uint16</code>\n</li><li><strong>Knotenelemente:</strong> Startknoten (Initial Node), eine Aktionsstufe (Action) sowie ein Endknoten (Activity Final Node)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und geht direkt in die Verarbeitungsaktion über.\n</li><li>In der Aktion werden zwei Bytes aus dem Array <code>Data</code> an den Positionen <code>Offset+2</code> und <code>Offset+3</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) ausgelesen und in die lokale Variable <code>ReceivedCounter</code> (<code>uint16</code>) geschrieben.\n</li><li>Nach Ausführung der Zuweisung wird der Kontrollfluss zum Aktivitätsendknoten weitergeleitet, womit dieser Teilschritt abgeschlossen ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[PRS_E2E_00776]</code> / <code>RS_E2E_08539</code>. Entwickler müssen sicherstellen, dass das übergebene PDU-Datenarray mindestens die Länge <code>Offset + 4</code> aufweist (bzw. zuvor über den Längen-Check validiert wurde), um Pufferüberläufe beim Zugriff auf <code>Offset+2</code> und <code>Offset+3</code> zu verhindern. Die Auswertung der Byte-Reihenfolge muss strikt in Big-Endian-Konvention erfolgen, unabhängig von der nativen Endianness der Host-CPU.</p>"}], "trans": [{"from": "FIG-2df02b29ca908172", "to": "FIG-befc310f0bc857c1", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
